const input = $json.body ?? $json;
const jobId = input.jobId;
if (!jobId || !/^[0-9a-f-]{36}$/i.test(jobId)) throw new Error('Invalid jobId');
return [{json: {...input, jobId}}];

let scenes = $('Get Scenes').all().map(item => item.json);
if (!Array.isArray(scenes) || scenes.length === 0) throw new Error('No scenes found for job');

const job = scenes[0].video_jobs || {};
const effectiveDuration = Number(job.effective_duration);
if (job.audio_mode === 'custom_audio') {
  if (!Number.isFinite(effectiveDuration) || effectiveDuration <= 0) throw new Error('CUSTOM_AUDIO_DURATION_REQUIRED');
  const sourceTotal = scenes.reduce((sum, scene) => sum + (Number(scene.duration_seconds) || 0), 0);
  if (sourceTotal <= 0) throw new Error('SCENE_DURATION_REQUIRED');
  let allocated = 0;
  scenes = scenes.map((scene, index) => {
    const duration = index === scenes.length - 1
      ? Math.round((effectiveDuration - allocated) * 100) / 100
      : Math.round(((Number(scene.duration_seconds) || 0) / sourceTotal) * effectiveDuration * 100) / 100;
    allocated += duration;
    return { ...scene, duration_seconds: duration };
  });
}

const jobId = $('Validate Input').first().json.jobId;

function formatTime(t) {
  const h = Math.floor(t / 3600);
  const m = Math.floor((t % 3600) / 60);
  const s = Math.floor(t % 60);
  const cs = Math.round((t % 1) * 100);
  return h + ':' + String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0') + '.' + String(cs).padStart(2,'0');
}

let ass = '[Script Info]\nScriptType: v4.00+\nPlayResX: 1080\nPlayResY: 1920\nScaledBorderAndShadow: yes\n\n';
ass += '[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n';
ass += 'Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,2,1,2,10,10,40,1\n\n';
ass += '[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n';

let currentTime = 0;
for (const s of scenes) {
  const dur = Number(s.duration_seconds) || 5;
  const start = formatTime(currentTime);
  const end = formatTime(currentTime + dur);
  const caption = (s.caption || '').replace(/\\/g, '\\\\').replace(/{/g, '\\{').replace(/}/g, '\\}').replace(/\n/g, '\\N');
  ass += 'Dialogue: 0,' + start + ',' + end + ',Default,,0,0,0,,' + caption + '\n';
  currentTime += dur;
}

const captionsPath = '/data/jobs/' + jobId + '/captions.ass';
const content = Buffer.from(ass, 'utf8');
return [{
  json: { jobId, captionsPath, sceneCount: scenes.length, fileSize: content.length, effectiveDuration: currentTime },
  binary: { data: { data: content.toString('base64'), mimeType: 'text/ass', fileName: 'captions.ass' } }
}];

const input = $json.body ?? $json;
const jobId = input.jobId ?? input.id;
if (!jobId || !input.workerId || !input.leaseToken || input.attemptNumber == null || input.pipelineRevision == null) throw new Error('LEASE_CONTEXT_REQUIRED');
const stage = 'build_captions';
const itemKey = input.itemKey ?? ('job' === 'scene_set' ? 'all-scenes' : 'job');
const canonical = JSON.stringify({jobId, pipelineRevision: input.pipelineRevision, stage, itemKey, revision: input.currentRevision ?? input.pipelineRevision});
return [{json: {...input, jobId, stage, itemKey, stageHashInput: canonical, workerId: input.workerId, leaseToken: input.leaseToken, attemptNumber: Number(input.attemptNumber), pipelineRevision: Number(input.pipelineRevision)}}];

const {stageHashInput, ...context} = $('Hash Stage Input').first().json;
const result = $json;
return [{json: {...context, stageState: result.state, stageRunId: result.stage_run_id, runToken: result.run_token, cachedOutput: result.output}}];

const context = $('Merge Stage Context').first().json;
if ($json.permitted !== true) throw new Error('EXTERNAL_ATTEMPT_LIMIT');
return [{json: {...context, externalAttempt: $json.attempt_number}}];

const context = $('Merge Stage Context').first().json;
if (context.stageState !== 'CACHED_SUCCESS') throw new Error('STAGE_RECONCILIATION_REQUIRED');
return [{json: {success: true, cached: true, jobId: context.jobId, stage: context.stage, stageRunId: context.stageRunId, output: context.cachedOutput}}];
